// Capture execution metadata safely without logging secrets or full borrower PII
const errorData = $input.first().json;

const workflowName = errorData.workflow ? errorData.workflow.name : 'Unknown Workflow';
const executionId = errorData.execution ? errorData.execution.id : 'N/A';
const errorMessage = errorData.execution ? errorData.execution.error.message : 'Unknown Error';

return [{
  json: {
    workflow_name: workflowName,
    execution_id: executionId,
    error_message: errorMessage,
    timestamp: new Date().toISOString()
  }
}];
